<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { usersApi, type Address, type AddressPayload } from '../api/users'
import { useAuthStore } from '../stores/auth'

const auth = useAuthStore(), addresses = ref<Address[]>([]), loading = ref(true), showForm = ref(false), editingId = ref<string | null>(null), notice = ref('')
const profile = reactive({ fullName: auth.user?.fullName ?? '', phone: auth.user?.phone ?? '' })
const emptyAddress = (): AddressPayload => ({ recipientName: '', phone: '', province: '', district: '', ward: '', street: '', label: 'Nhà riêng', isDefault: false })
const addressForm = reactive<AddressPayload>(emptyAddress())
onMounted(async () => { try { addresses.value = await usersApi.getAddresses() } finally { loading.value = false } })
async function saveProfile() { const user = await usersApi.updateProfile(profile); auth.setUser({ ...auth.user!, ...user }); notice.value = 'Đã cập nhật hồ sơ.' }
function openAddress(item?: Address) { Object.assign(addressForm, item ?? emptyAddress()); editingId.value = item?.id ?? null; showForm.value = true }
async function saveAddress() { const item = editingId.value ? await usersApi.updateAddress(editingId.value, addressForm) : await usersApi.createAddress(addressForm); const index = addresses.value.findIndex(a => a.id === item.id); if (index >= 0) addresses.value[index] = item; else addresses.value.push(item); showForm.value = false }
async function removeAddress(id: string) { if (!confirm('Xóa địa chỉ này?')) return; await usersApi.deleteAddress(id); addresses.value = addresses.value.filter(a => a.id !== id) }
async function setDefault(id: string) { await usersApi.setDefaultAddress(id); addresses.value = addresses.value.map(a => ({ ...a, isDefault: a.id === id })) }
</script>
<template><div class="profile-page container"><aside class="profile-sidebar"><div class="profile-person"><span class="profile-avatar">{{ auth.user?.fullName.charAt(0) }}</span><div><strong>{{ auth.user?.fullName }}</strong><small>{{ auth.user?.email }}</small></div></div><nav><a class="active" href="#account">◉ Hồ sơ cá nhân</a><a href="#addresses">⌖ Địa chỉ của tôi</a><a href="#">▣ Đơn mua</a><a href="#">♡ Sản phẩm yêu thích</a></nav></aside><section class="profile-content"><div id="account" class="content-card"><div class="section-heading"><div><h1>Hồ sơ cá nhân</h1><p>Quản lý thông tin tài khoản của bạn</p></div></div><p v-if="notice" class="success-message">{{ notice }}</p><form class="profile-form" @submit.prevent="saveProfile"><div class="form-grid"><label>Họ và tên<input v-model="profile.fullName" required /></label><label>Số điện thoại<input v-model="profile.phone" type="tel" /></label></div><label>Email<input :value="auth.user?.email" disabled /><small>Email không thể thay đổi</small></label><button class="primary-button compact">Lưu thay đổi</button></form></div><div id="addresses" class="content-card"><div class="section-heading"><div><h2>Địa chỉ của tôi</h2><p>Địa chỉ dùng để nhận hàng</p></div><button class="outline-button" @click="openAddress()">＋ Thêm địa chỉ</button></div><p v-if="loading">Đang tải...</p><div v-else-if="!addresses.length" class="empty-state">⌖<strong>Chưa có địa chỉ</strong><span>Thêm địa chỉ để đặt hàng nhanh hơn.</span></div><article v-for="address in addresses" v-else :key="address.id" class="address-card"><div><div class="address-title"><strong>{{ address.recipientName }}</strong><span>{{ address.phone }}</span><em v-if="address.isDefault">Mặc định</em></div><p>{{ address.street }}, {{ address.ward }}, {{ address.district }}, {{ address.province }}</p></div><div class="address-actions"><button @click="openAddress(address)">Sửa</button><button v-if="!address.isDefault" @click="setDefault(address.id)">Đặt mặc định</button><button class="danger" @click="removeAddress(address.id)">Xóa</button></div></article></div></section><div v-if="showForm" class="modal-backdrop" @click.self="showForm = false"><form class="modal" @submit.prevent="saveAddress"><div class="section-heading"><h2>{{ editingId ? 'Sửa địa chỉ' : 'Thêm địa chỉ' }}</h2><button type="button" @click="showForm = false">✕</button></div><div class="form-grid"><label>Người nhận<input v-model="addressForm.recipientName" required /></label><label>Số điện thoại<input v-model="addressForm.phone" required /></label></div><label>Địa chỉ cụ thể<input v-model="addressForm.street" required /></label><div class="form-grid three"><label>Phường / Xã<input v-model="addressForm.ward" required /></label><label>Quận / Huyện<input v-model="addressForm.district" required /></label><label>Tỉnh / Thành phố<input v-model="addressForm.province" required /></label></div><label>Nhãn địa chỉ<input v-model="addressForm.label" placeholder="Nhà riêng, Văn phòng..." /></label><label class="check"><input v-model="addressForm.isDefault" type="checkbox" /> Đặt làm địa chỉ mặc định</label><button class="primary-button">Lưu địa chỉ</button></form></div></div></template>
